  `sign_status` varchar(20) NOT NULL DEFAULT 'pending' COMMENT '签署状态',
  `sign_flow_id` varchar(100) DEFAULT NULL COMMENT '签署流程ID',
  `sign_url` varchar(500) DEFAULT NULL COMMENT '签署链接',
  `sign_time` datetime DEFAULT NULL COMMENT '签署完成时间',
  `sign_log` json DEFAULT NULL COMMENT '签署日志',
  `file_id` varchar(100) DEFAULT NULL COMMENT '合同文件ID',
  `content` text COMMENT '合同内容（条款摘要）',
  `contract_html` longtext COMMENT '合同HTML内容（模板生成）',
  `content_version` int(11) NOT NULL DEFAULT '1' COMMENT '内容版本号',
