  `msg_type` tinyint(4) NOT NULL DEFAULT '1' COMMENT '消息类型 1-6',
  `title` varchar(200) NOT NULL COMMENT '消息标题(冗余)',
  `channel` varchar(20) NOT NULL COMMENT '发送渠道 inbox/email/sms/wechat/dingtalk/workwx',
