DROP TABLE IF EXISTS `warehouse_stock_flow`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `warehouse_stock_flow` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `material_id` int(11) NOT NULL DEFAULT '0' COMMENT '物料ID',
  `material_code` varchar(50) NOT NULL DEFAULT '' COMMENT '物料/产品编码（冗余）',
  `material_name` varchar(200) NOT NULL DEFAULT '' COMMENT '物料/产品名称（冗余）',
  `flow_type` tinyint(1) NOT NULL DEFAULT '0' COMMENT '变动类型：1采购入库 2生产领料 3成品入库 4销售出库 5调拨入库 6调拨出库 7盘盈 8盘亏 9报废出库',
  `flow_quantity` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '变动数量（正增负减）',
  `before_stock` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '变动前库存',
  `after_stock` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '变动后库存',
  `cost_price` decimal(14,4) NOT NULL DEFAULT '0.0000' COMMENT '成本单价（元）',
  `cost_total` decimal(18,4) NOT NULL DEFAULT '0.0000' COMMENT '成本总价（元）',
  `before_avg_price` decimal(14,4) NOT NULL DEFAULT '0.0000' COMMENT '变动前加权平均单价（元）',
  `after_avg_price` decimal(14,4) NOT NULL DEFAULT '0.0000' COMMENT '变动后加权平均单价（元）',
  `ref_type` varchar(30) NOT NULL DEFAULT '' COMMENT '关联单据类型',
  `ref_no` varchar(50) NOT NULL DEFAULT '' COMMENT '关联单据编号',
  `warehouse_id` int(11) NOT NULL DEFAULT '0' COMMENT '仓库ID',
  `location_id` int(11) NOT NULL DEFAULT '0' COMMENT '货位ID',
  `operator_id` int(11) NOT NULL DEFAULT '0' COMMENT '操作人ID',
  `operator_name` varchar(50) NOT NULL DEFAULT '' COMMENT '操作人姓名',
  `flow_time` datetime DEFAULT NULL COMMENT '变动时间',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `create_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_material_id` (`material_id`),
  KEY `idx_warehouse_id` (`warehouse_id`),
  KEY `idx_flow_time` (`flow_time`)
) ENGINE=InnoDB AUTO_INCREMENT=50 DEFAULT CHARSET=utf8mb4 COMMENT='库存流水表（当前库存=SUM(flow_quantity)）';
