INSERT INTO `ai_tools` VALUES (27,'query_system_stats','查询系统统计','common','查询系统整体统计（员工/设备/隐患/事故总数）——暂无聚合概览接口，预留','GET','',NULL,'{\"type\": \"object\", \"properties\": {}}',NULL,0,30,1,0,NULL,1,'active',19,'2026-08-08 02:54:53','2026-08-28 21:11:36');
