INSERT INTO `ai_tools` VALUES (29,'send_notification','发送通知','common','向指定用户发送系统通知消息（高风险写操作，需用户确认）','POST','/api/notification/send',NULL,'{\"type\": \"object\", \"required\": [\"target_ids\", \"title\", \"content\"], \"properties\": {\"title\": {\"type\": \"string\", \"title\": \"通知标题\", \"description\": \"必填\"}, \"content\": {\"type\": \"string\", \"title\": \"通知内容\", \"description\": \"必填\"}, \"link_url\": {\"type\": \"string\", \"title\": \"跳转链接\", \"description\": \"可选\"}, \"msg_type\": {\"enum\": [1, 2, 3, 4, 5, 6], \"type\": \"integer\", \"title\": \"消息类型\", \"default\": 1, \"description\": \"1系统公告 2任务指派 3审批通知 4预警提醒 5培训通知 6工单通知\"}, \"target_ids\": {\"type\": \"array\", \"items\": {\"type\": \"integer\"}, \"title\": \"接收人ID列表\", \"description\": \"必填\"}, \"target_type\": {\"enum\": [\"user\", \"dept\", \"all\"], \"type\": \"string\", \"title\": \"接收类型\", \"default\": \"user\"}}}',NULL,1,30,1,0,NULL,1,'active',21,'2026-08-08 02:54:53','2026-08-28 21:11:36');
INSERT INTO `ai_tools` VALUES (36,'query_customer','查询客户详情','business','根据客户ID查询客户详细信息，包括客户编码、名称、类型、所属行业、区域、客户等级、联系人、联系方式、信用额度、地址等，含订单数/接收数/合同数统计。适用于查看特定客户的完整资料、客户画像分析等场景。','GET','/api/business/customer/detail/{id}',NULL,'{\"type\": \"object\", \"properties\": {\"id\": {\"type\": \"integer\", \"required\": true, \"description\": \"客户ID\"}}}',NULL,0,30,1,0,NULL,1,'active',0,'2026-08-16 02:52:05','2026-08-16 02:52:05');
INSERT INTO `ai_tools` VALUES (37,'list_customers','查询客户列表','business','查询客户列表，支持按客户名称/编码关键词、客户类型、客户等级、所属行业、区域、状态、分类等多条件筛选，返回分页结果。适用于客户盘点、客户排行分析、客户筛选等场景。','GET','/api/business/customer/list',NULL,'{\"type\": \"object\", \"properties\": {\"page\": {\"type\": \"integer\", \"default\": 1, \"required\": false, \"description\": \"页码\"}, \"limit\": {\"type\": \"integer\", \"default\": 20, \"required\": false, \"description\": \"每页条数\"}, \"region\": {\"type\": \"string\", \"required\": false, \"description\": \"所属区域\"}, \"status\": {\"type\": \"integer\", \"required\": false, \"description\": \"状态：1启用 0停用\"}, \"keyword\": {\"type\": \"string\", \"required\": false, \"description\": \"客户名称/编码/简称/联系人关键词\"}, \"industry\": {\"type\": \"string\", \"required\": false, \"description\": \"所属行业\"}, \"category_id\": {\"type\": \"integer\", \"required\": false, \"description\": \"客户分类ID\"}, \"customer_type\": {\"type\": \"string\", \"required\": false, \"description\": \"客户类型\"}, \"customer_level\": {\"type\": \"string\", \"required\": false, \"description\": \"客户等级：A/B/C/D\"}}}',NULL,0,30,1,0,NULL,1,'active',0,'2026-08-16 02:52:05','2026-08-16 02:52:05');
INSERT INTO `ai_tools` VALUES (38,'query_product','查询产品详情','business','根据产品ID查询产品详细信息，包括产品编码、名称、规格型号、生产厂家、单位、分类、状态、当前位置等。适用于查看特定产品的完整资料、产品画像分析等场景。','GET','/api/business/product/detail/{id}',NULL,'{\"type\": \"object\", \"properties\": {\"id\": {\"type\": \"integer\", \"required\": true, \"description\": \"产品ID\"}}}',NULL,0,30,1,0,NULL,1,'active',0,'2026-08-16 02:52:05','2026-08-16 02:52:05');
INSERT INTO `ai_tools` VALUES (39,'list_products','查询产品列表','business','查询产品列表，支持按产品名称、产品编码、分类、状态等多条件筛选，返回分页结果。适用于产品盘点、产品排行分析、产品筛选等场景。','GET','/api/business/product/list',NULL,'{\"type\": \"object\", \"properties\": {\"page\": {\"type\": \"integer\", \"default\": 1, \"required\": false, \"description\": \"页码\"}, \"status\": {\"type\": \"integer\", \"required\": false, \"description\": \"状态：1启用 0停用\"}, \"pageSize\": {\"type\": \"integer\", \"default\": 10, \"required\": false, \"description\": \"每页条数\"}, \"category_id\": {\"type\": \"integer\", \"required\": false, \"description\": \"产品分类ID\"}, \"product_code\": {\"type\": \"string\", \"required\": false, \"description\": \"产品编码（模糊）\"}, \"product_name\": {\"type\": \"string\", \"required\": false, \"description\": \"产品名称（模糊）\"}}}',NULL,0,30,1,0,NULL,1,'active',0,'2026-08-16 02:52:05','2026-08-16 02:52:05');
INSERT INTO `ai_tools` VALUES (40,'query_order','查询订单详情','business','根据订单ID查询订单详细信息，包括订单编号、类别、客户、联系人、下单/交付日期、金额、状态、业务员、明细、操作日志、评审记录等。适用于查看特定订单的完整资料、订单异常分析等场景。','GET','/api/business/order/detail/{id}',NULL,'{\"type\": \"object\", \"properties\": {\"id\": {\"type\": \"integer\", \"required\": true, \"description\": \"订单ID\"}}}',NULL,0,30,1,0,NULL,1,'active',0,'2026-08-16 02:52:05','2026-08-16 02:52:05');
INSERT INTO `ai_tools` VALUES (41,'list_orders','查询订单列表','business','查询订单列表，支持按订单编号/客户名称/业务员关键词、订单类别、订单状态、下单/交付日期范围、业务员等多条件筛选，返回分页结果。适用于订单盘点、销售趋势分析、业绩统计等场景。','GET','/api/business/order/list',NULL,'{\"type\": \"object\", \"properties\": {\"page\": {\"type\": \"integer\", \"default\": 1, \"required\": false, \"description\": \"页码\"}, \"limit\": {\"type\": \"integer\", \"default\": 20, \"required\": false, \"description\": \"每页条数\"}, \"keyword\": {\"type\": \"string\", \"required\": false, \"description\": \"订单编号/客户名称/业务员关键词\"}, \"order_end\": {\"type\": \"string\", \"required\": false, \"description\": \"下单结束日期 YYYY-MM-DD\"}, \"order_start\": {\"type\": \"string\", \"required\": false, \"description\": \"下单开始日期 YYYY-MM-DD\"}, \"delivery_end\": {\"type\": \"string\", \"required\": false, \"description\": \"交付结束日期 YYYY-MM-DD\"}, \"order_status\": {\"type\": \"string\", \"required\": false, \"description\": \"订单状态：draft/reviewed/completed/cancelled 等\"}, \"delivery_start\": {\"type\": \"string\", \"required\": false, \"description\": \"交付开始日期 YYYY-MM-DD\"}, \"order_category\": {\"type\": \"string\", \"required\": false, \"description\": \"订单类别：sales/repair 等\"}, \"salesperson_id\": {\"type\": \"integer\", \"required\": false, \"description\": \"业务员ID\"}}}',NULL,0,30,1,0,NULL,1,'active',0,'2026-08-16 02:52:05','2026-08-16 02:52:05');
INSERT INTO `ai_tools` VALUES (42,'query_supplier','查询供应商详情','business','根据供应商ID查询供应商详细信息，包括供应商编码、名称、类型、供应品类、评级（A/B/C/D）、所属区域、联系人、联系方式、资质证照、状态等。适用于查看特定供应商完整资料、供应商评估分析等场景。','GET','/api/business/supplier/detail/{id}',NULL,'{\"type\": \"object\", \"properties\": {\"id\": {\"type\": \"integer\", \"required\": true, \"description\": \"供应商ID\"}}}',NULL,0,30,1,0,NULL,1,'active',0,'2026-08-16 03:02:56','2026-08-16 03:02:56');
INSERT INTO `ai_tools` VALUES (43,'list_suppliers','查询供应商列表','business','查询供应商列表，支持按名称/编码关键词、供应商类型、评级（supplier_level A/B/C/D）、供应品类、区域、状态、分类等多条件筛选，返回分页结果。适用于供应商盘点、供应商评估、采购决策等场景。','GET','/api/business/supplier/list',NULL,'{\"type\": \"object\", \"properties\": {\"page\": {\"type\": \"integer\", \"default\": 1, \"required\": false, \"description\": \"页码\"}, \"limit\": {\"type\": \"integer\", \"default\": 20, \"required\": false, \"description\": \"每页条数\"}, \"region\": {\"type\": \"string\", \"required\": false, \"description\": \"所属区域\"}, \"status\": {\"type\": \"integer\", \"required\": false, \"description\": \"状态：1启用 0停用\"}, \"keyword\": {\"type\": \"string\", \"required\": false, \"description\": \"供应商名称/编码/简称/联系人关键词\"}, \"category_id\": {\"type\": \"integer\", \"required\": false, \"description\": \"供应商分类ID\"}, \"supplier_type\": {\"type\": \"string\", \"required\": false, \"description\": \"供应商类型\"}, \"supplier_level\": {\"type\": \"string\", \"required\": false, \"description\": \"供应商评级：A/B/C/D\"}, \"supply_category\": {\"type\": \"string\", \"required\": false, \"description\": \"供应品类\"}}}',NULL,0,30,1,0,NULL,1,'active',0,'2026-08-16 03:02:56','2026-08-16 03:02:56');
INSERT INTO `ai_tools` VALUES (44,'query_contract','查询合同详情','business','根据合同ID查询合同详细信息，包括合同编号、名称、类型、甲方/乙方（客户/供应商）、合同金额、签订/生效/到期日期、签署状态、履约状态、内容摘要等。适用于查看特定合同完整资料、合同履约分析等场景。','GET','/api/business/contract/detail/{id}',NULL,'{\"type\": \"object\", \"properties\": {\"id\": {\"type\": \"integer\", \"required\": true, \"description\": \"合同ID\"}}}',NULL,0,30,1,0,NULL,1,'active',0,'2026-08-16 03:02:56','2026-08-16 03:02:56');
INSERT INTO `ai_tools` VALUES (45,'list_contracts','查询合同列表','business','查询合同列表，支持按合同编号/名称/客户/供应商关键词、合同类型、合同状态、签署状态、签订日期范围、金额区间等多条件筛选，返回分页结果。适用于合同盘点、合同履约监控、合同统计分析等场景。','GET','/api/business/contract/list',NULL,'{\"type\": \"object\", \"properties\": {\"page\": {\"type\": \"integer\", \"default\": 1, \"required\": false, \"description\": \"页码\"}, \"limit\": {\"type\": \"integer\", \"default\": 20, \"required\": false, \"description\": \"每页条数\"}, \"party\": {\"type\": \"string\", \"required\": false, \"description\": \"甲方/乙方（客户或供应商）名称模糊\"}, \"keyword\": {\"type\": \"string\", \"required\": false, \"description\": \"合同编号/名称/客户/供应商关键词\"}, \"sign_end\": {\"type\": \"string\", \"required\": false, \"description\": \"签订结束日期 YYYY-MM-DD\"}, \"amount_max\": {\"type\": \"number\", \"required\": false, \"description\": \"合同金额上限\"}, \"amount_min\": {\"type\": \"number\", \"required\": false, \"description\": \"合同金额下限\"}, \"sign_start\": {\"type\": \"string\", \"required\": false, \"description\": \"签订开始日期 YYYY-MM-DD\"}, \"sign_status\": {\"type\": \"string\", \"required\": false, \"description\": \"签署状态\"}, \"contract_type\": {\"type\": \"string\", \"required\": false, \"description\": \"合同类型\"}, \"contract_status\": {\"type\": \"string\", \"required\": false, \"description\": \"合同状态\"}}}',NULL,0,30,1,0,NULL,1,'active',0,'2026-08-16 03:02:56','2026-08-16 03:02:56');
INSERT INTO `ai_tools` VALUES (46,'query_quotation','查询报价单详情','business','根据报价单ID查询报价单详细信息，包括报价编号、类别、客户、业务员、报价日期、总金额、有效期、状态及明细列表等。适用于查看特定报价单完整资料、报价分析等场景。','GET','/api/business/quotation/detail/{id}',NULL,'{\"type\": \"object\", \"properties\": {\"id\": {\"type\": \"integer\", \"required\": true, \"description\": \"报价单ID\"}}}',NULL,0,30,1,0,NULL,1,'active',0,'2026-08-16 03:02:56','2026-08-16 03:02:56');
INSERT INTO `ai_tools` VALUES (47,'list_quotations','查询报价单列表','business','查询报价单列表，支持按报价编号/客户/业务员关键词、报价类别、报价状态、报价日期范围、有效期范围、业务员等多条件筛选，返回分页结果。适用于报价单盘点、报价跟进、成交率分析等场景。','GET','/api/business/quotation/list',NULL,'{\"type\": \"object\", \"properties\": {\"page\": {\"type\": \"integer\", \"default\": 1, \"required\": false, \"description\": \"页码\"}, \"limit\": {\"type\": \"integer\", \"default\": 20, \"required\": false, \"description\": \"每页条数\"}, \"keyword\": {\"type\": \"string\", \"required\": false, \"description\": \"报价编号/客户名称/业务员关键词\"}, \"date_end\": {\"type\": \"string\", \"required\": false, \"description\": \"报价结束日期 YYYY-MM-DD\"}, \"date_start\": {\"type\": \"string\", \"required\": false, \"description\": \"报价开始日期 YYYY-MM-DD\"}, \"salesperson_id\": {\"type\": \"integer\", \"required\": false, \"description\": \"业务员ID\"}, \"quotation_status\": {\"type\": \"string\", \"required\": false, \"description\": \"报价状态\"}, \"quotation_category\": {\"type\": \"string\", \"required\": false, \"description\": \"报价类别\"}}}',NULL,0,30,1,0,NULL,1,'active',0,'2026-08-16 03:02:56','2026-08-16 03:02:56');
INSERT INTO `ai_tools` VALUES (48,'query_purchase_order','查询采购订单详情','business','根据采购订单ID查询采购订单详细信息，包括采购编号、标题、供应商、下单日期、总金额、订单状态、付款状态、审批状态、收货数量及明细列表等。适用于查看特定采购订单完整资料、采购执行分析等场景。','GET','/api/business/purchase/order/detail/{id}',NULL,'{\"type\": \"object\", \"properties\": {\"id\": {\"type\": \"integer\", \"required\": true, \"description\": \"采购订单ID\"}}}',NULL,0,30,1,0,NULL,1,'active',0,'2026-08-16 03:02:56','2026-08-16 03:02:56');
INSERT INTO `ai_tools` VALUES (49,'list_purchase_orders','查询采购订单列表','business','查询采购订单列表，支持按采购编号、标题、供应商ID、采购申请单号、订单状态、付款状态、审批状态、下单日期范围等多条件筛选，返回分页结果（含状态数量统计）。适用于采购订单盘点、采购进度追踪、供应商绩效分析等场景。','GET','/api/business/purchase/order/list',NULL,'{\"type\": \"object\", \"properties\": {\"page\": {\"type\": \"integer\", \"default\": 1, \"required\": false, \"description\": \"页码\"}, \"title\": {\"type\": \"string\", \"required\": false, \"description\": \"采购标题（模糊）\"}, \"end_date\": {\"type\": \"string\", \"required\": false, \"description\": \"下单结束日期 YYYY-MM-DD\"}, \"order_no\": {\"type\": \"string\", \"required\": false, \"description\": \"采购编号（模糊）\"}, \"pageSize\": {\"type\": \"integer\", \"default\": 10, \"required\": false, \"description\": \"每页条数\"}, \"request_no\": {\"type\": \"string\", \"required\": false, \"description\": \"采购申请单号（模糊）\"}, \"start_date\": {\"type\": \"string\", \"required\": false, \"description\": \"下单开始日期 YYYY-MM-DD\"}, \"supplier_id\": {\"type\": \"integer\", \"required\": false, \"description\": \"供应商ID\"}, \"order_status\": {\"type\": \"integer\", \"required\": false, \"description\": \"订单状态：0草稿 1待审 2已审 3部分收货 4已收货 5已关闭 6已作废\"}, \"payment_status\": {\"type\": \"integer\", \"required\": false, \"description\": \"付款状态：0未付 1部分 2已付\"}, \"approval_status\": {\"type\": \"integer\", \"required\": false, \"description\": \"审批状态：0待提交 1审批中 2通过 3驳回\"}}}',NULL,0,30,1,0,NULL,1,'active',0,'2026-08-16 03:02:56','2026-08-16 03:02:56');
INSERT INTO `ai_tools` VALUES (50,'query_salary','查询员工薪酬明细','hr','按薪酬月份和员工姓名查询工资计算明细，返回基本工资、计件工资、津贴、扣款、应发工资、实发工资等构成。适用于查看员工薪酬详情、薪酬核对等场景。','GET','/api/hr/salary/payroll/list',NULL,'{\"type\": \"object\", \"properties\": {\"page\": {\"type\": \"integer\", \"default\": 1, \"required\": false, \"description\": \"页码\"}, \"month\": {\"type\": \"string\", \"required\": false, \"description\": \"薪酬月份 YYYY-MM（默认当月）\"}, \"pageSize\": {\"type\": \"integer\", \"default\": 10, \"required\": false, \"description\": \"每页条数\"}, \"user_name\": {\"type\": \"string\", \"required\": false, \"description\": \"员工姓名（模糊）\"}}}',NULL,0,30,1,0,NULL,1,'active',0,'2026-08-16 03:02:56','2026-08-16 03:02:56');
INSERT INTO `ai_tools` VALUES (51,'list_salary_slips','查询工资条列表','hr','查询工资条列表，支持按薪酬月份、员工姓名、部门、状态等多条件筛选，返回分页结果（含各状态统计）。适用于薪酬统计、工资条发放管理、薪酬成本分析等场景。','GET','/api/hr/salary/slip/list',NULL,'{\"type\": \"object\", \"properties\": {\"page\": {\"type\": \"integer\", \"default\": 1, \"required\": false, \"description\": \"页码\"}, \"month\": {\"type\": \"string\", \"required\": false, \"description\": \"薪酬月份 YYYY-MM\"}, \"status\": {\"type\": \"integer\", \"required\": false, \"description\": \"状态：1已发放 2已签收 3未签收\"}, \"slip_no\": {\"type\": \"string\", \"required\": false, \"description\": \"工资条编号（模糊）\"}, \"pageSize\": {\"type\": \"integer\", \"default\": 10, \"required\": false, \"description\": \"每页条数\"}, \"user_name\": {\"type\": \"string\", \"required\": false, \"description\": \"员工姓名（模糊）\"}, \"department_id\": {\"type\": \"integer\", \"required\": false, \"description\": \"部门ID\"}}}',NULL,0,30,1,0,NULL,1,'active',0,'2026-08-16 03:02:56','2026-08-16 03:02:56');
INSERT INTO `ai_tools` VALUES (52,'list_recruit_positions','查询招聘职位列表','hr','查询招聘职位列表，支持按职位名称、职位编号、部门、发布状态等多条件筛选，返回分页结果。适用于招聘进度追踪、职位发布管理、招聘统计分析等场景。','GET','/api/hr/recruit/position/list',NULL,'{\"type\": \"object\", \"properties\": {\"page\": {\"type\": \"integer\", \"default\": 1, \"required\": false, \"description\": \"页码\"}, \"pageSize\": {\"type\": \"integer\", \"default\": 10, \"required\": false, \"description\": \"每页条数\"}, \"position_no\": {\"type\": \"string\", \"required\": false, \"description\": \"职位编号（模糊）\"}, \"department_id\": {\"type\": \"integer\", \"required\": false, \"description\": \"部门ID\"}, \"position_name\": {\"type\": \"string\", \"required\": false, \"description\": \"职位名称（模糊）\"}, \"publish_status\": {\"type\": \"integer\", \"required\": false, \"description\": \"发布状态：0草稿 1发布中 2已截止 3已关闭\"}}}',NULL,0,30,1,0,NULL,1,'active',0,'2026-08-16 03:02:56','2026-08-16 03:02:56');
INSERT INTO `ai_tools` VALUES (53,'search_knowledge','搜索知识库文档','ai','在企业AI知识库中按关键词检索文档切片，返回匹配的文档片段（含相似度评分）。注意：kb_id 必填（知识库标识，可通过知识库列表获取）；当前为关键词检索，向量检索待接入后升级。适用于查找设备维修手册、安全操作规程、培训课件、事故案例等企业知识文档。','POST','/api/ai/knowledge/retrieve',NULL,'{\"type\": \"object\", \"properties\": {\"kb_id\": {\"type\": \"string\", \"required\": true, \"description\": \"知识库ID（必填）\"}, \"query\": {\"type\": \"string\", \"required\": true, \"description\": \"检索关键词或问题（必填）\"}, \"top_k\": {\"type\": \"integer\", \"default\": 5, \"required\": false, \"description\": \"返回结果条数（1-20）\"}}}',NULL,0,30,1,0,NULL,1,'active',0,'2026-08-16 03:02:56','2026-08-16 03:02:56');
