INSERT INTO `business_contract_clauses` VALUES (380,8,'第一条　序号、名称、型号、数量、价款等。','第一条　序号、名称、型号、数量、价款等。',0,'2026-08-12 00:48:14','2026-08-12 00:48:14');
INSERT INTO `business_contract_clauses` VALUES (381,8,'第二条　付款方式：','预付款30%，发货前付40%，验收合格付25%，质保金5%',1,'2026-08-12 00:48:14','2026-08-12 00:48:14');
INSERT INTO `business_contract_clauses` VALUES (382,8,'第三条　质量标准：','确保设备或设施满足甲方的使用需求。',2,'2026-08-12 00:48:14','2026-08-12 00:48:14');
INSERT INTO `business_contract_clauses` VALUES (383,8,'第四条　交货方式及运输费用：','由乙方负责。',3,'2026-08-12 00:48:14','2026-08-12 00:48:14');
INSERT INTO `business_contract_clauses` VALUES (384,8,'第五条　验收期限：','收到货后7日内验收，逾期不验收视为合格。',4,'2026-08-12 00:48:14','2026-08-12 00:48:14');
INSERT INTO `business_contract_clauses` VALUES (385,8,'第六条　合同争议解决方式：','本合同履行过程中发生的争议，由双方协商解决，协商不成的，提交需方当地人民法院起诉处理。',5,'2026-08-12 00:48:14','2026-08-12 00:48:14');
INSERT INTO `business_contract_clauses` VALUES (386,8,'第七条　违约责任：','按《民法典》规定，违约方承担相应违约责任。',6,'2026-08-12 00:48:14','2026-08-12 00:48:14');
INSERT INTO `business_contract_clauses` VALUES (387,8,'第八条　本合同一式四份，甲乙双方各持两份。','第八条　本合同一式四份，甲乙双方各持两份。',7,'2026-08-12 00:48:14','2026-08-12 00:48:14');
INSERT INTO `business_contract_clauses` VALUES (388,8,'第九条　本合同经双方法定代表人或委托代理人签字盖章后生效。','第九条　本合同经双方法定代表人或委托代理人签字盖章后生效。',8,'2026-08-12 00:48:14','2026-08-12 00:48:14');
